/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { APP_CONFIG } from '../config/app-config.service';
import { AppConfig, emptyConfig, ThemeConfig } from '../config/app-config.model';
import { AppStateService } from '../state/app-state.service';
import { ThemeModeService } from './theme-mode.service';
import { DEFAULT_LOGO, resolveBrand, RuntimeThemeService } from './runtime-theme.service';

describe('RuntimeThemeService', () => {
  const style = () => document.documentElement.style;
  let config: ReturnType<typeof signal<AppConfig>>;
  let tenant: ReturnType<typeof signal<string>>;
  let dark: ReturnType<typeof signal<boolean>>;

  function withTheme(theme: ThemeConfig, meta = {}): AppConfig {
    return { ...emptyConfig('test'), theme, meta };
  }

  function create(): RuntimeThemeService {
    const service = TestBed.inject(RuntimeThemeService);
    TestBed.tick();
    return service;
  }

  beforeEach(() => {
    config = signal(emptyConfig('test'));
    tenant = signal('main');
    dark = signal(false);
    TestBed.configureTestingModule({
      providers: [
        { provide: APP_CONFIG, useValue: config },
        { provide: AppStateService, useValue: { tenant } },
        { provide: ThemeModeService, useValue: { dark } },
      ],
    });
  });

  afterEach(() => {
    ['--mat-sys-primary', '--app-nav-width'].forEach((name) => style().removeProperty(name));
  });

  it('applies theme.tokens on <html> once the configuration loads', () => {
    create();
    expect(style().getPropertyValue('--mat-sys-primary')).toBe('');

    config.set(withTheme({ tokens: { '--mat-sys-primary': 'rgb(1, 2, 3)' } }));
    TestBed.tick();

    expect(style().getPropertyValue('--mat-sys-primary')).toBe('rgb(1, 2, 3)');
  });

  it('applies the active tenant tokens and removes the ones that no longer apply', () => {
    config.set(
      withTheme({
        tokens: { '--mat-sys-primary': 'red' },
        tenants: { acme: { tokens: { '--mat-sys-primary': 'blue', '--app-nav-width': '300px' } } },
      }),
    );
    create();
    expect(style().getPropertyValue('--mat-sys-primary')).toBe('red');

    tenant.set('acme');
    TestBed.tick();
    expect(style().getPropertyValue('--mat-sys-primary')).toBe('blue');
    expect(style().getPropertyValue('--app-nav-width')).toBe('300px');

    tenant.set('main');
    TestBed.tick();
    expect(style().getPropertyValue('--mat-sys-primary')).toBe('red');
    expect(style().getPropertyValue('--app-nav-width')).toBe('');
  });

  it('resolves the logo by mode and falls back to the default one', () => {
    const service = create();
    expect(service.logo()).toBe(DEFAULT_LOGO);

    config.set(withTheme({ logo: 'light.svg', 'logo-dark': 'dark.svg' }));
    expect(service.logo()).toBe('light.svg');
    dark.set(true);
    expect(service.logo()).toBe('dark.svg');
  });

  it('uses theme.product-name or, if missing, meta.title', () => {
    const service = create();
    config.set(withTheme({}, { title: 'Phylax' }));
    expect(service.productName()).toBe('Phylax');

    config.set(withTheme({ 'product-name': 'Acme' }, { title: 'Phylax' }));
    expect(service.productName()).toBe('Acme');
  });

  it('does not mix the global dark logo with a tenant logo', () => {
    const brand = resolveBrand({ logo: 'a.svg', 'logo-dark': 'a-dark.svg', tenants: { b: { logo: 'b.svg' } } }, 'b');
    expect(brand.logo).toBe('b.svg');
    expect(brand['logo-dark']).toBeUndefined();
  });
});
